package com.warrioraspirants.app;

import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;

public class MainActivity extends Activity {
 int navy=Color.rgb(11,23,54), red=Color.rgb(214,40,40), white=Color.WHITE; LinearLayout root,content;
 TextView title,subtitle;
 @Override public void onCreate(Bundle b){super.onCreate(b); showSplash();}
 TextView tv(String s,float z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setPadding(20,10,20,10);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 GradientDrawable bg(int color,float r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(r);return g;}
 void showSplash(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(Gravity.CENTER);l.setBackgroundColor(navy);TextView a=tv("WARRIOR ASPIRANTS",30,white,true);TextView q=tv("Build the Empire.\nThe Queen Will Come.",18,Color.LTGRAY,true);q.setGravity(17);l.addView(a);l.addView(q);setContentView(l);a.setAlpha(0f);q.setAlpha(0f);a.animate().alpha(1).setDuration(700);q.animate().alpha(1).setStartDelay(450).setDuration(700);new Handler().postDelayed(this::home,2200);}
 void home(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(246,247,250));LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.VERTICAL);head.setPadding(18,18,18,8);head.setBackgroundColor(navy);head.addView(tv("WARRIOR ASPIRANTS",23,white,true));head.addView(tv("Your preparation. Your mission.",14,Color.LTGRAY,false));root.addView(head,new LinearLayout.LayoutParams(-1,-2));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(16,12,16,8);ScrollView sv=new ScrollView(this);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(white);String[] n={"Home","Study","Practice","Current Affairs","Profile"};for(String x:n){Button b=new Button(this);b.setText(x);b.setTextSize(11);b.setAllCaps(false);b.setOnClickListener(v->page(x));nav.addView(b,new LinearLayout.LayoutParams(0,60,1));}root.addView(nav);setContentView(root);page("Home");}
 void page(String p){content.removeAllViews();content.addView(tv(p,26,navy,true));if(p.equals("Home")){card("TODAY'S PREPARATION","Maths • 60 min\nReasoning • 45 min\nEnglish • 45 min\nGK/GS • 30 min");card("PROGRESS","Preparation 0%\n🔥 Streak 0 days\nAccuracy —\nNext Mission: Start your first lesson");card("QUICK ACTIONS","📚 Study Room    📝 Practice\n🎯 PYQ Engine     🧠 Fighter AI\n🏆 Mock Tests     🔄 Revision");}else if(p.equals("Study")){card("STUDY ROOM","Maths\nReasoning\nEnglish\nGK / GS\nCurrent Affairs\n\nSequence: Beginner → Basic → Advanced");}else if(p.equals("Practice")){card("PRACTICE ARENA","10 Questions • 20 Questions • 50 Questions\nEasy • Moderate • Hard\nTimer • Speed • Accuracy\n\nWrong answers automatically enter your Mistake Book.");}else if(p.equals("Current Affairs")){card("CURRENT AFFAIRS","Daily Current Affairs\nWeekly Revision\nMonthly One-Liners\nDaily Quiz\n\nFresh content will be connected to the app later.");}else {card("PROFILE","Warrior Level 1\nXP 0\nStreak 0 days\n\nTarget Exams\nSSC CGL • Railway • UP SI");}}
 void card(String h,String body){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(12,12,12,12);c.setBackground(bg(white,28));c.setElevation(4);TextView a=tv(h,16,red,true);TextView b=tv(body,15,Color.DKGRAY,false);c.addView(a);c.addView(b);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,8,0,8);content.addView(c,lp);}
}
